import * as THREE from 'three';
import type { Vec3 } from '../contracts/math';

const OFFSCREEN = 1_000_000;
const DEFAULT_COLOR: ParticleColor = { r: 1, g: 1, b: 1 };
const DEFAULT_VELOCITY: Vec3 = { x: 0, y: 0, z: 0 };

export interface ParticleColor {
  r: number;
  g: number;
  b: number;
}

export interface ParticleManagerOptions {
  scene?: THREE.Scene;
  capacity?: number;
  pointSize?: number;
  gravity?: number;
  opacity?: number;
  depthWrite?: boolean;
}

export interface ParticleSpawnOptions {
  position: Vec3;
  velocity?: Vec3;
  color?: ParticleColor;
  count?: number;
  spread?: number;
  lifetime?: number;
  gravity?: number;
  drag?: number;
  random?: () => number;
}

/** Fixed-capacity particle pool backed by one Points draw call. */
export class ParticleManager {
  readonly points: THREE.Points<THREE.BufferGeometry, THREE.PointsMaterial>;
  readonly capacity: number;

  private readonly positions: Float32Array;
  private readonly colors: Float32Array;
  private readonly baseColors: Float32Array;
  private readonly velocities: Float32Array;
  private readonly ages: Float32Array;
  private readonly lifetimes: Float32Array;
  private readonly gravities: Float32Array;
  private readonly drags: Float32Array;
  private readonly active: Int32Array;
  private readonly free: Int32Array;
  private activeCountValue = 0;
  private freeCount: number;
  private readonly defaultGravity: number;
  private disposed = false;

  constructor(options: ParticleManagerOptions = {}) {
    const capacity = Math.floor(options.capacity ?? 256);
    if (!Number.isFinite(capacity) || capacity < 1) {
      throw new Error('ParticleManager capacity must be a positive finite integer');
    }
    this.capacity = capacity;
    this.defaultGravity = options.gravity ?? -9.81;
    this.positions = new Float32Array(capacity * 3);
    this.colors = new Float32Array(capacity * 3);
    this.baseColors = new Float32Array(capacity * 3);
    this.velocities = new Float32Array(capacity * 3);
    this.ages = new Float32Array(capacity);
    this.lifetimes = new Float32Array(capacity);
    this.gravities = new Float32Array(capacity);
    this.drags = new Float32Array(capacity);
    this.active = new Int32Array(capacity);
    this.free = new Int32Array(capacity);
    this.freeCount = capacity;

    const geometry = new THREE.BufferGeometry();
    geometry.setAttribute('position', new THREE.BufferAttribute(this.positions, 3));
    geometry.setAttribute('color', new THREE.BufferAttribute(this.colors, 3));
    geometry.setDrawRange(0, capacity);
    for (let index = 0; index < capacity; index += 1) {
      this.free[index] = capacity - index - 1;
      this.writeInactive(index);
    }
    geometry.getAttribute('position').needsUpdate = true;

    const material = new THREE.PointsMaterial({
      color: 0xffffff,
      size: options.pointSize ?? 0.12,
      sizeAttenuation: true,
      vertexColors: true,
      transparent: true,
      opacity: options.opacity ?? 1,
      depthWrite: options.depthWrite ?? false,
    });
    this.points = new THREE.Points(geometry, material);
    this.points.name = 'particle-pool';
    this.points.frustumCulled = false;
    options.scene?.add(this.points);
  }

  get activeCount(): number { return this.activeCountValue; }
  get availableCount(): number { return this.freeCount; }

  emit(options: ParticleSpawnOptions): number {
    if (this.disposed) return 0;
    const count = Math.max(0, Math.floor(options.count ?? 1));
    const lifetime = Math.max(0.001, options.lifetime ?? 0.65);
    const velocity = options.velocity ?? DEFAULT_VELOCITY;
    const color = options.color ?? DEFAULT_COLOR;
    const spread = Math.max(0, options.spread ?? 0);
    const random = options.random ?? Math.random;
    let emitted = 0;

    while (emitted < count && this.freeCount > 0) {
      const index = this.numberAt(this.free, --this.freeCount);
      const offset = index * 3;
      const xJitter = spread === 0 ? 0 : (random() * 2 - 1) * spread;
      const yJitter = spread === 0 ? 0 : (random() * 2 - 1) * spread;
      const zJitter = spread === 0 ? 0 : (random() * 2 - 1) * spread;
      this.positions[offset] = options.position.x + xJitter;
      this.positions[offset + 1] = options.position.y + yJitter;
      this.positions[offset + 2] = options.position.z + zJitter;
      this.velocities[offset] = velocity.x;
      this.velocities[offset + 1] = velocity.y;
      this.velocities[offset + 2] = velocity.z;
      this.colors[offset] = this.baseColors[offset] = color.r;
      this.colors[offset + 1] = this.baseColors[offset + 1] = color.g;
      this.colors[offset + 2] = this.baseColors[offset + 2] = color.b;
      this.ages[index] = 0;
      this.lifetimes[index] = lifetime;
      this.gravities[index] = options.gravity ?? this.defaultGravity;
      this.drags[index] = Math.max(0, options.drag ?? 0);
      this.active[this.activeCountValue++] = index;
      emitted += 1;
    }
    if (emitted > 0) this.markAttributesDirty();
    return emitted;
  }

  update(deltaSeconds: number): void {
    if (this.disposed || this.activeCountValue === 0) return;
    const dt = Math.min(Math.max(deltaSeconds, 0), 0.1);
    if (dt === 0) return;
    let slot = 0;
    let changed = false;
    while (slot < this.activeCountValue) {
      const index = this.numberAt(this.active, slot);
      const age = this.numberAt(this.ages, index) + dt;
      const lifetime = this.numberAt(this.lifetimes, index);
      if (age >= lifetime) {
        this.releaseAt(slot);
        changed = true;
        continue;
      }
      const offset = index * 3;
      const damping = 1 / (1 + this.numberAt(this.drags, index) * dt);
      const velocityX = this.numberAt(this.velocities, offset) * damping;
      const velocityY = (this.numberAt(this.velocities, offset + 1) + this.numberAt(this.gravities, index) * dt) * damping;
      const velocityZ = this.numberAt(this.velocities, offset + 2) * damping;
      this.velocities[offset] = velocityX;
      this.velocities[offset + 1] = velocityY;
      this.velocities[offset + 2] = velocityZ;
      this.positions[offset] = this.numberAt(this.positions, offset) + velocityX * dt;
      this.positions[offset + 1] = this.numberAt(this.positions, offset + 1) + velocityY * dt;
      this.positions[offset + 2] = this.numberAt(this.positions, offset + 2) + velocityZ * dt;
      const fade = 1 - age / lifetime;
      this.colors[offset] = this.numberAt(this.baseColors, offset) * fade;
      this.colors[offset + 1] = this.numberAt(this.baseColors, offset + 1) * fade;
      this.colors[offset + 2] = this.numberAt(this.baseColors, offset + 2) * fade;
      this.ages[index] = age;
      slot += 1;
      changed = true;
    }
    if (changed) this.markAttributesDirty();
  }

  clear(): void {
    if (this.disposed || this.activeCountValue === 0) return;
    while (this.activeCountValue > 0) this.releaseAt(this.activeCountValue - 1);
    this.markAttributesDirty();
  }

  dispose(): void {
    if (this.disposed) return;
    this.disposed = true;
    this.points.removeFromParent();
    this.points.geometry.dispose();
    this.points.material.dispose();
  }

  private releaseAt(slot: number): void {
    const index = this.numberAt(this.active, slot);
    const lastSlot = --this.activeCountValue;
    this.active[slot] = this.numberAt(this.active, lastSlot);
    this.free[this.freeCount++] = index;
    this.writeInactive(index);
  }

  private writeInactive(index: number): void {
    const offset = index * 3;
    this.positions[offset] = OFFSCREEN;
    this.positions[offset + 1] = OFFSCREEN;
    this.positions[offset + 2] = OFFSCREEN;
    this.colors[offset] = 0;
    this.colors[offset + 1] = 0;
    this.colors[offset + 2] = 0;
  }

  private markAttributesDirty(): void {
    this.points.geometry.getAttribute('position').needsUpdate = true;
    this.points.geometry.getAttribute('color').needsUpdate = true;
  }

  private numberAt(buffer: Float32Array | Int32Array, index: number): number {
    return buffer[index] ?? 0;
  }
}
